// polkit-regra.js — evaluates the polkit rule generated by tools/instalar.sh against a fake polkit object.
// Usage: node tools/sim/polkit-regra.js RULE_FILE USER     (prints "polkit ok" or "ERRO ..." lines; exit 1 on error)
'use strict';
const fs = require('fs');
const vm = require('vm');
const [arquivo, usuario] = process.argv.slice(2);
const Result = { NO: 'no', YES: 'yes', AUTH_SELF: 'auth_self', AUTH_ADMIN: 'auth_admin', NOT_HANDLED: null };
const regras = [];
const polkit = { Result, addRule: (f) => regras.push(f), log: () => {}, spawn: () => { throw new Error('spawn not allowed'); } };
// polkit runs rules on Duktape (ES5.1): reject newer syntax a node-only check would let through.
const fonte = fs.readFileSync(arquivo, 'utf8');
if (/=>|\blet\b|\bconst\b|`|\?\.|\?\?/.test(fonte.replace(/\/\/.*$/gm, ''))) { console.log('ERRO: regra usa sintaxe além do ES5'); process.exit(1); }
vm.runInNewContext(fonte, { polkit });
if (regras.length !== 1) { console.log('ERRO: esperava 1 regra, veio ' + regras.length); process.exit(1); }

function decide(id, detalhes, user) {
  const action = { id, lookup: (k) => detalhes[k] };
  const r = regras[0](action, { user, local: true, active: true, isInGroup: () => false });
  return r === undefined ? null : r;
}
const M = 'org.freedesktop.systemd1.manage-units';
const casos = [
  // [description, action id, details, user, expected]
  ['restart openrange', M, { unit: 'openrange.service', verb: 'restart' }, usuario, 'yes'],
  ['start openrange', M, { unit: 'openrange.service', verb: 'start' }, usuario, 'yes'],
  ['stop openrange', M, { unit: 'openrange.service', verb: 'stop' }, usuario, 'yes'],
  ['reset-failed openrange (saude)', M, { unit: 'openrange.service', verb: 'reset-failed' }, usuario, 'yes'],
  ['kill openrange', M, { unit: 'openrange.service', verb: 'kill' }, usuario, null],
  ['restart other unit', M, { unit: 'sshd.service', verb: 'restart' }, usuario, null],
  ['unit name prefix trick', M, { unit: 'openrange.service.d', verb: 'restart' }, usuario, null],
  ['other user', M, { unit: 'openrange.service', verb: 'restart' }, 'outro', null],
  ['enable (unit files)', 'org.freedesktop.systemd1.manage-unit-files', { unit: 'openrange.service', verb: 'enable' }, usuario, null],
  ['no details', M, {}, usuario, null],
];
let erros = 0;
for (const [nome, id, det, user, esperado] of casos) {
  const r = decide(id, det, user);
  if (r !== esperado) { console.log('ERRO polkit: ' + nome + ' → ' + r + ' (esperado ' + esperado + ')'); erros++; }
}
console.log(erros ? 'polkit: ' + erros + ' erro(s)' : 'polkit ok (' + casos.length + ' casos)');
process.exit(erros ? 1 : 0);
